export const parentData = {
  id: 0,
  attribute_id: '',
  parent_attribute_id: null,
  parent_product_attribute_id: null,
  type: '',
  showTable: false,
  tableData: [],
  className: 'normal',
  is_array: false,
  showAddButton: false,
  deleteButton: false,
  disableSelectField: true,
  category_id: '',
  name: '',
  code: '',
  datatype: ''
}

export const formInitialData = (data) => {
  const newData = []
  let modifiedData = modificationData([data])
  let otherSiblings = [...modifiedData[0].nested]
  const firstData = {
    ...parentData,
    attribute_id: modifiedData[0].attribute_id || '',
    category_id: modifiedData[0].category_id,
    name: modifiedData[0].name,
    datatype: modifiedData[0].datatype,
    id: modifiedData[0].id,
    code: modifiedData[0].code,
    type: modifiedData[0].attribute_type,
    is_array: modifiedData[0].is_array,
    parent_attribute_id: modifiedData[0].parent_attribute_id,
    parent_product_attribute_id: modifiedData[0].parent_product_attribute_id
  }
  const modifiedSiblings = modifiedSblingsData(otherSiblings)
  newData.push(firstData)
  return [...newData, ...modifiedSiblings]
}

export function modifiedSblingsData (data) {
  let datalength = data.length
  function traverse (data) {
    for (let i = 0; i < data.length; i++) {
      if (data[i].nested.length === 0) {
        data[i] = {
          ...parentData,
          attribute_id: data[i].attribute_id || '',
          id: data[i].id,
          code: data[i].code,
          type: data[i].attribute_type,
          className: 'child',
          category_id: data[i].category_id,
          name: data[i].name,
          datatype: data[i].datatype,
          nested: data[i].nested,
          parent_product_attribute_id: data[i].parent_product_attribute_id,
          showAddButton: ((datalength - 1) === i)
        }
      } else {
        data[i] = {
          ...parentData,
          attribute_id: data[i].attribute_id || '',
          id: data[i].id,
          code: data[i].code,
          type: data[i].attribute_type,
          className: 'child',
          nested: data[i].nested,
          showTable: true,
          category_id: data[i].category_id,
          name: data[i].name,
          datatype: data[i].datatype,
          tableData: data[i].nested,
          parent_product_attribute_id: data[i].parent_product_attribute_id,
          showAddButton: ((datalength - 1) === i)
        }
        traverse(data[i].nested)
      }
    }
  }
  traverse(data)
  return data
}

export function modificationData (data = []) {
  return data.map(item => {
    if (item.hasOwnProperty('children')) {
      delete item.children
    }
    if (item.nested.length > 0) {
      modificationData(item.nested)
    }
    return item
  })
}

export function payloadMapper (item, type) {
  return {
    attribute_id: item.attribute_id,
    parent_attribute_id: item.parent_product_attribute_id,
    is_array: item.is_array === 'false' ? false : item.is_array,
    attribute_type: type
  }
}

export function finalEditPayloadMapper (data, type) {
  let newData = []
  function traverse (data, type) {
    for (let i = 0; i < data.length; i++) {
      if (data[i].tableData.length === 0) {
        newData.push(payloadMapper(data[i], type))
      } else {
        newData.push(payloadMapper(data[i], type))
        traverse(data[i].tableData, type)
      }
    }
  }
  traverse(data, type)
  return newData
}

export function payloadValues (data, count) {
  const newData = []
  while (count !== 0) {
    newData.push(data[data.length - 1])
    data.pop()
    count--
  }
  return newData
}
