export function unique (arr) {
  // Store the unique
  let uniques = []
  // Track the items added to the uniques
  let itemsFound = {}
  for (let val of arr) {
    // If item is already added then move to the next item
    if (itemsFound[val.name]) {
      continue
    }
    // Else push it to the unique list
    uniques.push(val)
    // Mark it as added
    itemsFound[val.name] = true
  }
  // Return the uniques
  return uniques
}
export function uniquesAttributes (arr) {
  let flags = []
  let output = []
  let l = arr.length

  for (let i = 0; i < l; i++) {
    if (arr[i].parent_attribute_id === null) {
      if (!output.includes({ id: arr[i].attribute_id, type: arr[i].attribute_type })) {
        flags.push(arr[i])
        output.push({
          id: arr[i].attribute_id,
          type: arr[i].attribute_type
        })
      } 
    } else {
      flags.push(arr[i])
    }
  }
  return flags
}
