import { get } from 'lodash'

export function defaultChildAdd (parentData, selectedTemplateData) {
  const childLength = parentData.length - 1
  return {
    id: childLength + 1,
    attribute_id: '',
    parent_attribute_id: get(selectedTemplateData, 'attribute_id', ''),
    parent_product_attribute_id: get(selectedTemplateData, 'attribute_id', ''),
    className: 'child',
    is_array: false,
    showTable: false,
    tableData: [],
    type: '',
    showAddButton: true,
    deleteButton: true,
    disableSelectField: false
  }
}

export function addTableChilds (item) {
  return {
    id: 0,
    attribute_id: '',
    parent_attribute_id: get(item, 'attribute_id', ''),
    parent_product_attribute_id: get(item, 'attribute_id', ''),
    className: 'child',
    is_array: false,
    showTable: false,
    tableData: [],
    type: '',
    showAddButton: true,
    deleteButton: true
  }
}
