import React from 'react'
import { Form, Row, Col, Button, Select } from 'antd'
import { get } from 'lodash'

import { addTableChilds } from './addChildHandler'
import { OptionSpan } from './index.style'
import { unique } from '../../../../util/dataUniqueness'
import { getFormItems } from '../../../../components/formItem'

const { Option } = Select
class NormalFieldData extends React.Component {
  state = {
    selectedTemplate: {},
    templateData: []
  }

  componentDidMount () {
    const { templateData, form } = this.props
    form.resetFields()
    const modifiedData = templateData.filter(item => item.datatype !== 'object')
    if (this.state.templateData !== modifiedData) {
      this.setState({
        templateData: modifiedData
      })
    }
  }

  handleSelectChange = (value) => {
    const { form, templateData } = this.props
    const selectedTemplate = templateData.find(item => item.id === value) || []
    this.setState({
      selectedTemplate
    })
    Object.keys(selectedTemplate).forEach((item) => {
      form.setFieldsValue({
        [item]: selectedTemplate[item]
      })
    })
  }

  validateForm = async () => {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  handleSubmit = async (e) => {
    e.preventDefault()
    const { form, item } = this.props
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const formBody = form.getFieldsValue()
    let tableAttributes = addTableChilds(item)
    tableAttributes = {
      ...tableAttributes,
      ...formBody,
      id: item.tableData.length + 1,
      attribute_id: get(formBody, 'category_id', ''),
      type: get(formBody, 'datatype', '')
    }
    const tableData = {
      ...item,
      tableData: unique([...item.tableData, tableAttributes])
    }
    this.props.onUpdateTable(tableData)
  }

  render () {
    const { getFieldDecorator } = this.props.form
    const { templateData, selectedTemplate } = this.state
    return (
      <Row type='flex' justify='center'>
        <Col span={20}>
          <Form onSubmit={this.handleSubmit}>
            <Row type='flex' justify='center'>
              <Col span={13}>
                <p>Choose from Template</p>
              </Col>
              <Col span={13}>
                <Form.Item>
                  {
                    getFieldDecorator('category_id', {
                      rules: [
                        {
                          required: true
                        }
                      ]
                      // initialValue: false
                    })(
                      <Select
                        showSearch
                        filterOption={(input, option) => option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                        onChange={this.handleSelectChange}
                      >
                        {templateData.map((item, index) => (
                          <Option
                            key={index}
                            value={item.id}
                            searchValue={`${item.name} ${item.is_system_attribute ? 'System Attribute' : ''}`}
                          >
                            <OptionSpan>
                              {item.name} {item.is_system_attribute ? <b className='system-tag'>System</b> : ''}
                            </OptionSpan>
                          </Option>
                        ))}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
            </Row>

            <Row type='flex' justify='center'>
              <Col span={13}>
                <p>Field code</p>
              </Col>
              <Col span={13}>
                {
                  getFormItems.call(this, {
                    formName: 'code',
                    type: 'alphanumeric',
                    required: true,
                    className: 'small-size',
                    disableField: true,
                    initialValue: get(selectedTemplate, 'code', '')
                    // validator: validator.checkValidator
                  })
                }
              </Col>
            </Row>
            <Row type='flex' justify='center'>
              <Col span={13}>
                <p>Field name</p>
              </Col>
              <Col span={13}>
                {
                  getFormItems.call(this, {
                    formName: 'name',
                    type: 'alphanumeric',
                    required: true,
                    className: 'small-size',
                    disableField: true,
                    initialValue: get(selectedTemplate, 'name', '')
                    // validator: validator.checkValidator
                  })
                }
              </Col>
            </Row>
            <Row type='flex' justify='center'>
              <Col span={13}>
                <p>Field type</p>
              </Col>
              <Col span={13}>
                {
                  getFormItems.call(this, {
                    formName: 'datatype',
                    type: 'alphanumeric',
                    required: true,
                    className: 'small-size',
                    disableField: true,
                    initialValue: get(selectedTemplate, 'datatype', '')
                    // validator: validator.checkValidator
                  })
                }
              </Col>
            </Row>
            <Row type='flex' justify='center'>
              <Col span={13}>
                {
                  getFormItems.call(this, {
                    formName: 'is_array',
                    type: 'checkbox',
                    require: false,
                    className: 'small-size',
                    label: 'is array data type',
                    initialValue: get(selectedTemplate, 'is_array', false)
                  })
                }
              </Col>
            </Row>
            <Row type='flex' justify='center' gutter={40}>
              <Col>
                <Button type='default' onClick={() => this.props.closeModal()}>Cancel</Button>
              </Col>
              <Col>
                <Button type='primary' htmlType='submit'>Submit</Button>
              </Col>
            </Row>
          </Form>
        </Col>
      </Row>
    )
  }
}
const WrappedDataForm = Form.create()(NormalFieldData)

export default WrappedDataForm
