import React from 'react'
import PropTypes from 'prop-types'
import { Row, Col, Form, Select, Icon, Button, Checkbox, notification } from 'antd'
import { get, size } from 'lodash'

import { getFormItems } from '../../../../components/formItem'
import TableWrapper from '../../../../components/Table'
import ModalWrapper from '../../../../components/Modal'
import { Step2TableColumns } from '../../../../constants/Step2Table'

import FieldItemStyleWrapper, { FormItemStyleWrapper, OptionSpan } from './index.style'
import { defaultChildAdd } from './addChildHandler'
import NormaFieldData from './normalFieldData'
import { templateName } from './dataFormation'

const { Option } = Select

class FormItems extends React.Component {
  static propTypes = {
    item: PropTypes.object.isRequired,
    onlyRegular: PropTypes.bool.isRequired,
    templateData: PropTypes.arrayOf(PropTypes.object),
    parentData: PropTypes.arrayOf(PropTypes.object)
  }

  static defaultProps = {
    item: {},
    templateData: [],
    onlyRegular: true,
    parentData: []
  }

  constructor (props) {
    super(props)
    this.state = {
      initialTemplateData: [],
      newTemplateData: [],
      modalVisible: false,
      activeButton: 'regular'
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      templateData
    } = nextProps
    if (size(templateData) !== size(this.state.initialTemplateData)) {
      const newTemplateData = templateData.filter(item => item.datatype !== 'object')
      this.setState({
        newTemplateData,
        initialTemplateData: templateData
      })
    }
  }
  // shouldComponentUpdate (nextProps, nextState) {
  //   const { newTemplateData } = nextState
  //   const { templateData } = nextProps
  //   return (size(templateData) !== size(newTemplateData))
  // }

  componentDidMount () {
    const { templateData, item } = this.props
    const newTemplateData = templateData.filter(item => item.datatype !== 'object')

    this.setState({
      newTemplateData,
      initialTemplateData: templateData,
      activeButton: get(item, 'datatype') === 'object' ? 'object' : 'regular'
    })
  }

  selectHandler = (value, id) => {
    const { form, item, parentData, step2Data } = this.props
    const { initialTemplateData } = this.state
    const selectedTemplateData = initialTemplateData.find(item => item.id === value) || []

    Object.keys(selectedTemplateData).forEach((item) => {
      form.setFieldsValue({
        category_id: selectedTemplateData.id,
        [item]: selectedTemplateData[item]
      })
    })
    const formData = { ...form.getFieldsValue() }
    const attributefinder = step2Data ? step2Data.find((item) => item.attribute_id === value) || {} : {}
    if (size(attributefinder) > 0 && get(item, 'parent_product_attribute_id') === null) {
      notification.error({
        message: `Attributes ${get(attributefinder, 'name')} already created on root level`
      })
      form.resetFields()
    } else {
      if (item.parent_product_attribute_id === null) {
        const parendModified = {
          ...item,
          type: get(formData, 'datatype', ''),
          is_array: get(formData, 'is_array', 'false'),
          attribute_id: get(formData, 'category_id', '')
        }
        if (get(formData, 'datatype', '') === 'object') {
          const conditionalParentData = parentData.length > 1 ? [parentData[0]] : parentData
          const newChildData = defaultChildAdd(conditionalParentData, parendModified)
          window.sessionStorage.setItem('nestedAttributes', JSON.stringify([parendModified, newChildData]))
          this.props.updateData([parendModified, newChildData])
        } else {
          window.sessionStorage.setItem('nestedAttributes', JSON.stringify([parendModified]))
          this.props.updateData([parendModified])
        }
      } else {
        const siblings = {
          ...item,
          type: get(formData, 'datatype', ''),
          is_array: get(formData, 'is_array', 'false'),
          attribute_id: get(formData, 'category_id', '')
        }
        const newParent = parentData.map((ele, index) => {
          if (ele.id === item.id) {
            ele = siblings
          }
          return ele
        })
        window.sessionStorage.setItem('nestedAttributes', JSON.stringify(newParent))
        this.props.updateData(newParent)
      }
    }
  }

  addHandler = (item) => {
    const { parentData } = this.props
    const childData = defaultChildAdd(parentData, parentData[0])
    const oldData = parentData.map((item, index) => {
      if (index > 0) {
        item.showAddButton = false
      }
      return item
    })
    const newParent = [...oldData, childData]
    window.sessionStorage.setItem('nestedAttributes', JSON.stringify(newParent))
    this.props.updateData(newParent)
  }

  removeHandler = (id) => {
    const { parentData } = this.props
    const newParentData = parentData.filter(item => item.id !== id)
    newParentData[newParentData.length - 1] = {
      ...newParentData[newParentData.length - 1],
      showAddButton: true
    }
    window.sessionStorage.setItem('nestedAttributes', JSON.stringify(newParentData))
    this.props.updateData(newParentData)
  }

  onChangeCheckBox = (e, id) => {
    const { parentData } = this.props
    const newParentData = parentData.map((item) => {
      if (item.id === id) {
        item.is_array = e.target.checked
      }
      return item
    })
    window.sessionStorage.setItem('nestedAttributes', JSON.stringify(newParentData))
    this.props.updateData(newParentData)
  }
  // Regular Button

  regularHandler = (item) => {
    const { parentData } = this.props
    const { initialTemplateData } = this.state
    const localData = initialTemplateData.filter(item => item.datatype !== 'object')
    this.setState({
      newTemplateData: localData,
      activeButton: 'regular'
    })

    // condition for changing mid level attribute type
    if (item.parent_product_attribute_id !== null) {
      this.props.form.resetFields()
      const modifiedItem = {
        ...item,
        showTable: false,
        tableData: []
      }
      const newParentData = parentData.map((item, index) => {
        if (item.id === modifiedItem.id) {
          item = modifiedItem
        }
        return item
      })
      window.sessionStorage.setItem('nestedAttributes', JSON.stringify(newParentData))
      this.props.updateData(newParentData)
    }
  }

  // Object Button
  objectHandler = (item) => {
    const { parentData } = this.props
    const { initialTemplateData } = this.state
    const localData = initialTemplateData.filter(item => item.datatype === 'object')
    this.setState({
      newTemplateData: localData,
      activeButton: 'object'
    })

    // Condition for table needs to add here (if item is child then table show)
    if (item.parent_product_attribute_id !== null) {
      this.props.form.resetFields()
      const modifiedItem = {
        ...item,
        showTable: true
      }
      const newParentData = parentData.map((item, index) => {
        if (item.id === modifiedItem.id) {
          item = modifiedItem
        }
        return item
      })
      window.sessionStorage.setItem('nestedAttributes', JSON.stringify(newParentData))
      this.props.updateData(newParentData)
    }
  }

  handleUpdateTable = (data) => {
    const { parentData } = this.props
    const newParentData = parentData.map((item, index) => {
      if (item.id === data.id) {
        item = data
      }
      return item
    })
    window.sessionStorage.setItem('nestedAttributes', JSON.stringify(newParentData))
    this.props.updateData(newParentData)

    this.closeModalHandler()
  }

  handleOpenModal = () => {
    this.setState({
      modalVisible: true
    })
  }

  closeModalHandler = () => {
    this.setState({
      modalVisible: false
    })
  }

  render () {
    const {
      item,
      onlyRegular
    } = this.props
    const { newTemplateData, modalVisible, activeButton, initialTemplateData } = this.state

    const { getFieldDecorator } = this.props.form
    return (
      <FieldItemStyleWrapper>
        {
          modalVisible &&
            <ModalWrapper
              title={`Regular Attribute (${(templateName(item.attribute_id, initialTemplateData))})`}
              visible={modalVisible}
              centered
              closable
              cancelSubmit={this.closeModalHandler}
            >
              <NormaFieldData
                item={item}
                templateData={initialTemplateData}
                onUpdateTable={this.handleUpdateTable}
                closeModal={this.closeModalHandler}
              />
            </ModalWrapper>
        }
        <Row type='flex' justify='center'>
          <Col span={16} style={{ padding: 15 }}>
            <Row type='flex' justify='center' align='middle' gutter={20}>
              <Col span={16}>
                <FormItemStyleWrapper border={item.className}>
                  {
                    onlyRegular &&
                      <Row className='button-section' type='flex' justify='space-around'>
                        <Col>
                          <Button className={activeButton === 'regular' && 'colored-button'} disabled={item.disableSelectField} onClick={() => this.regularHandler(item)}>Regular</Button>
                        </Col>
                        <Col>
                          <Button className={activeButton === 'object' && 'colored-button'} disabled={item.disableSelectField} onClick={() => this.objectHandler(item)}>Object</Button>
                        </Col>
                      </Row>
                  }
                  <Row type='flex' justify='center'>
                    <Col span={24}>
                      <Form>
                        <div className={item.className}>
                          <Row type='flex' justify='center'>
                            <Col span={13}>
                              <p>Choose from Template</p>
                            </Col>
                            <Col span={13}>
                              <Form.Item>
                                {
                                  getFieldDecorator('category_id', {
                                    rules: [
                                      {
                                        required: true
                                      }
                                    ],
                                    initialValue: item.name || false
                                  })(
                                    <Select
                                      showSearch
                                      filterOption={(input, option) => option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                                      disabled={item.disableSelectField}
                                      onChange={(e) => this.selectHandler(e, item.id)}
                                    >
                                      {newTemplateData.map((item, index) => (
                                        <Option
                                          key={index}
                                          value={item.id}
                                          searchValue={`${item.name} ${item.is_system_attribute ? 'System Attribute' : ''}`}
                                        >
                                          <OptionSpan>
                                            {item.name} {item.is_system_attribute ? <b className='system-tag'>System</b> : ''}
                                          </OptionSpan>
                                        </Option>
                                      ))}
                                    </Select>
                                  )
                                }
                              </Form.Item>
                            </Col>
                          </Row>
                          <Row type='flex' justify='center'>
                            <Col span={13}>
                              <p>Field code</p>
                            </Col>
                            <Col span={13}>
                              {
                                getFormItems.call(this, {
                                  formName: 'code',
                                  type: 'alphanumeric',
                                  required: true,
                                  className: 'small-size',
                                  disableField: true,
                                  initialValue: item.code || ''
                                  // validator: validator.checkValidator
                                })
                              }
                            </Col>
                          </Row>
                          <Row type='flex' justify='center'>
                            <Col span={13}>
                              <p>Field name</p>
                            </Col>
                            <Col span={13}>
                              {
                                getFormItems.call(this, {
                                  formName: 'name',
                                  type: 'alphanumeric',
                                  required: true,
                                  className: 'small-size',
                                  disableField: true,
                                  initialValue: item.name || ''
                                  // validator: validator.checkValidator
                                })
                              }
                            </Col>
                          </Row>
                          <Row type='flex' justify='center'>
                            <Col span={13}>
                              <p>Field type</p>
                            </Col>
                            <Col span={13}>
                              {
                                getFormItems.call(this, {
                                  formName: 'datatype',
                                  type: 'alphanumeric',
                                  required: true,
                                  className: 'small-size',
                                  disableField: true,
                                  initialValue: item.datatype || ''
                                  // validator: validator.checkValidator
                                })
                              }
                            </Col>
                          </Row>
                          <Row type='flex' justify='center'>
                            <Col span={13}>
                              <Form.Item>
                                {
                                  getFieldDecorator('is_array', {
                                    rules: [
                                      {
                                        required: true
                                      }
                                    ],
                                    valuePropName: 'checked',
                                    initialValue: item.is_array || false

                                  })(<Checkbox disabled={item.disableSelectField} onChange={(e) => this.onChangeCheckBox(e, item.id)}>is array data type</Checkbox>)
                                }
                              </Form.Item>
                            </Col>
                          </Row>
                        </div>
                      </Form>
                    </Col>
                    <Col span={20}>
                      {
                        (item.type && item.showTable) &&
                          <Row type='flex' justify='center'>
                            <Col span={24}>
                              <Row type='flex' justify='space-around' align='middle'>
                                <Col>
                                  <p><b>Keys</b></p>
                                </Col>
                                <Col>
                                  <Button type='primary' onClick={this.handleOpenModal}>Add Keys</Button>
                                </Col>
                              </Row>
                            </Col>
                            <Col span={24}>
                              <div>
                                <TableWrapper
                                  bordered
                                  columns={Step2TableColumns}
                                  dataSource={item.tableData}
                                />
                              </div>
                            </Col>
                          </Row>
                      }
                    </Col>
                  </Row>
                </FormItemStyleWrapper>
              </Col>
              <Col span={2}>
                <div className='icon-div'>
                  {
                    item.showAddButton &&
                      <Icon
                        className='dynamic-add-button button-size'
                        type='plus-circle'
                        theme='filled'
                        onClick={() => this.addHandler(item)}
                      />
                  }
                  {
                    item.deleteButton &&
                      <Icon
                        style={{ marginLeft: 5 }}
                        className='dynamic-delete-button button-size'
                        type='minus-circle'
                        theme='filled'
                        onClick={() => this.removeHandler(item.id)}
                      />
                  }
                </div>
              </Col>
            </Row>
          </Col>
        </Row>

      </FieldItemStyleWrapper>
    )
  }
}
const WrappedDataForm = Form.create()(FormItems)

export default WrappedDataForm
